#!/usr/bin/env python
# -*- coding: utf-8 -*-
#
# ydk-wayland alias table generator.
#
# gdkaliasdef.c (generated by makegdkalias.pl) is a checked-in description of
# the public-symbol alias table: for every exported gdk_* symbol it records
# the per-file marker macro (__GDK_*_C__) that gates the corresponding
# `extern __typeof (...) ... alias ("IA__...")` declaration.
#
# Modern gcc refuses to emit that alias from a standalone TU because the
# IA__ target, while hidden-visible and declared in gdkalias.h, is never
# DEFINED in that translation unit.  The working pattern (verified against
# gcc 14) is to emit each alias in the SAME TU that defines the target -- i.e.
# appending the alias declaration to the backend/core source that actually
# defines the function.  The build then force-includes a per-source snippet
# into that source's TU; gcc resolves the target from the later definition.
#
# parse_marker_symbols() extracts the marker -> symbol mapping while applying
# the (simple) preprocessor gating present in gdkaliasdef.c.

import re

def parse_marker_symbols(path, extra_defined=()):
    """Return {marker: set(symbols)} for every symbol gdkaliasdef.c would
    emit in a TU where the given markers/macros are defined."""

    # Always-defined in real TUs (glib pulls G_HAVE_GNUC_VISIBILITY; the
    # build passes the config macros).
    defined = (set(extra_defined) |
               {'G_HAVE_GNUC_VISIBILITY', 'HAVE_CONFIG_H', '_REENTRANT',
                'GDK_COMPILATION', 'G_LOG_DOMAIN'})

    def repl_defined(m):
        return '1' if m.group(1) in defined else '0'

    marker_pat = r'__GDK[A-Z0-9_]*_C__'

    def eval_cond(expr):
        expr = re.sub(r'defined\s*\(\s*(\w+)\s*\)', repl_defined, expr)
        expr = re.sub(r'IN_FILE\((%s)\)' % marker_pat, repl_defined, expr)
        expr = re.sub(r'IN_HEADER\([^)]*\)', '1', expr)
        expr = re.sub(r'\b[A-Za-z_]\w*\b',
                      lambda m: '1' if m.group() in defined else '0', expr)
        return bool(eval(expr, {'__builtins__': {}}))

    out = {}
    cond_stack = [True]
    marker_stack = [None]

    for raw in open(path).read().splitlines():
        line = raw.strip()
        m = re.match(r'^\s*#(if|ifdef|ifndef)\b\s*(.*)$', raw)
        if m:
            kind, rest = m.group(1), m.group(2).strip()
            if kind == 'ifdef':
                cond = rest in defined
            elif kind == 'ifndef':
                cond = rest not in defined
            else:
                cond = eval_cond(rest)
            parent = cond_stack[-1]
            cond_stack.append(parent and cond)

            mm = re.match(r'^#if\s+IN_FILE\((%s)\)$' % marker_pat, line)
            marker_stack.append(mm.group(1) if (mm and cond_stack[-1])
                                else marker_stack[-1])
            continue

        if line.startswith('#endif'):
            if len(cond_stack) == 1:
                continue
            cond_stack.pop()
            marker_stack.pop()
            continue

        if not cond_stack[-1]:
            continue

        m = re.match(r'^#undef\s+(\w+)$', line)
        if m and m.group(1).startswith(('gdk', '_gdk')):
            sym = m.group(1)
            cur = marker_stack[-1]
            if cur:
                out.setdefault(cur, set()).add(sym)

    return out


def parse_defines(path):
    """Return the set of object-like #define names in a config header."""
    out = set()
    try:
        lines = open(path).read().splitlines()
    except IOError:
        return out
    for line in lines:
        m = re.match(r'^\s*#define\s+(\w+)', line)
        if m:
            out.add(m.group(1))
    return out


def active_definitions(content, defined):
    """Return the set of function names whose definition lines (name, '(' at
    column 0) occur in an active preprocessor region of `content`.

    `defined` should contain every macro that is defined when the file is
    compiled (build defines, config.h, per-file __GDK_*_C__ markers, ...).
    This is deliberately a SIMPLE preprocessor: it understands #if/#ifdef/
    #ifndef/#elif/#else/#endif, `defined(X)`, &&, ||, !, parentheses and
    numeric constants.  Expressions it cannot evaluate are assumed TRUE (the
    function is considered defined), which errs on the side of emitting an
    alias the compiler can then reject -- far better than silently dropping
    an exported symbol."""

    defined = set(defined or ())

    def _tokens(expr):
        i, n = 0, len(expr)
        while i < n:
            c = expr[i]
            if c.isspace():
                i += 1
                continue
            if c == '(':
                yield (c, c); i += 1; continue
            if c == ')':
                yield (c, c); i += 1; continue
            if c == '&' and expr[i:i + 2] == '&&':
                yield ('op', '&&'); i += 2; continue
            if c == '|' and expr[i:i + 2] == '||':
                yield ('op', '||'); i += 2; continue
            if c == '!':
                if expr[i:i + 2] == '!=':
                    yield ('op', '!='); i += 2
                else:
                    yield ('op', '!'); i += 1
                continue
            if c == '=' and expr[i:i + 2] == '==':
                yield ('op', '=='); i += 2; continue
            if c in '><':
                j = i
                while j < n and expr[j] in '><=':
                    j += 1
                yield ('op', expr[i:j]); i = j; continue
            if c.isalpha() or c == '_':
                j = i
                while j < n and (expr[j].isalnum() or expr[j] == '_'):
                    j += 1
                yield ('id', expr[i:j]); i = j; continue
            if c.isdigit():
                j = i
                while j < n and (expr[j].isalnum() or expr[j] in 'xX'):
                    j += 1
                tok = expr[i:j]
                try:
                    yield ('num', int(tok, 0))
                except ValueError:
                    yield ('num', int(tok, 10) if tok.isdigit() else 0)
                i = j; continue
            # anything else (e.g. other operators) -> treat as junk flag
            yield ('junk', c); i += 1

    class _BoolExpr(object):
        def __init__(self, toks):
            self.toks = list(toks)
            self.pos = 0

        def _peek(self):
            return self.toks[self.pos] if self.pos < len(self.toks) else None

        def _next(self):
            t = self._peek()
            self.pos += 1
            return t

        def parse(self):
            try:
                return self.or_expr()
            except Exception:
                return True  # unresolvable expression: assume active

        def or_expr(self):
            v = self.and_expr()
            while self._peek() and self._peek() == ('op', '||'):
                self._next()
                v = v or self.and_expr()
            return v

        def and_expr(self):
            v = self.unary()
            while self._peek() and self._peek() == ('op', '&&'):
                self._next()
                v = v and self.unary()
            return v

        def unary(self):
            t = self._peek()
            if t == ('op', '!'):
                self._next()
                return not self.unary()
            if t and t[0] == '(':
                self._next()
                v = self.or_expr()
                if self._peek() and self._peek()[0] == ')':
                    self._next()
                return v
            if t and t[0] == 'id':
                self._next()
                if t[1] == 'defined':
                    # optionally consume '(' NAME ')'
                    if self._peek() and self._peek()[0] == '(':
                        self._next()
                    nt = self._next()
                    name = nt[1] if nt and nt[0] in ('id',) else ''
                    if self._peek() and self._peek()[0] == ')':
                        self._next()
                    return name in defined
                return t[1] in defined
            if t and t[0] == 'op' and t[1] in ('==', '!=', '>=', '<=', '>', '<'):
                # comparison, e.g. __GNUC__ >= 3: treat numeric compare
                self._next()
                b = self.unary()
                a = t[1]
                return True  # cannot resolve reliably, assume active
            if t and (t[0] == 'num' or t[0] == 'junk'):
                self._next()
                return t[0] == 'num' and t[1] != 0
            return True

        def binary_remaining(self):
            return self.parse()

    def eval_cond(expr):
        return _BoolExpr(_tokens(expr)).parse()

    def_re = re.compile(r'^(\w+)\s*\(')
    found = set()
    stack = []          # (parent_active, taken)
    active = True
    in_block = False
    for raw in content.split('\n'):
        # strip comments (line-aware, block comments tracked)
        if in_block:
            end = raw.find('*/')
            if end < 0:
                continue
            raw = raw[end + 2:]
            in_block = False
        body = raw
        idx = body.find('//')
        if idx >= 0:
            body = body[:idx]
        while '/*' in body:
            s = body.find('/*')
            e = body.find('*/', s)
            if e < 0:
                in_block = True
                body = body[:s]
                break
            body = body[:s] + ' ' + body[e + 2:]
        line = body.strip()

        m = re.match(r'^#(if|ifdef|ifndef)\b\s*(.*)$', line)
        if m:
            kind, rest = m.group(1), m.group(2).strip()
            parent = active
            taken = False
            if parent:
                if kind == 'ifdef':
                    val = rest in defined
                elif kind == 'ifndef':
                    val = rest not in defined
                else:
                    val = eval_cond(rest)
                taken = val
                active = val
            else:
                active = False
            stack.append((parent, taken))
            continue

        m = re.match(r'^#elif\b\s*(.*)$', line)
        if m:
            parent, taken = stack[-1]
            if parent and not taken:
                val = eval_cond(m.group(1).strip())
                taken = val
                active = val
            else:
                active = False
            stack[-1] = (parent, taken)
            continue

        if line.startswith('#else'):
            parent, taken = stack[-1]
            if parent and not taken:
                taken = True
                active = True
            else:
                active = False
            stack[-1] = (parent, taken)
            continue

        if line.startswith('#endif'):
            if stack:
                parent, _ = stack.pop()
                active = parent
            continue

        if line.startswith('#'):
            # #define / #undef alter the local defined set
            m = re.match(r'^#(define|undef)\s+(\w+)\b', line)
            if m:
                if m.group(1) == 'define':
                    defined.add(m.group(2))
                else:
                    defined.discard(m.group(2))
            continue

        if active:
            # a real definition starts at column 0 and does not end with ';'
            # (that would be a call statement); indented calls are excluded
            # by the column-0 requirement.
            if not body[:1].isspace() and not body.rstrip().endswith(';'):
                m = def_re.match(body)
                if m:
                    found.add(m.group(1))

    return found


def render_aliases(symbols):
    """Render the alias declarations for a set of exported symbols.

    gdkalias.h is active in every TU and maps gdk_* -> IA__gdk_*.  Each alias
    line must therefore #undef the public name first (so the alias LHS stays
    the real exported name) and re-#define it afterwards (so the source code
    that follows, which defines the function the alias points to, still
    binds to the hidden IA__ name)."""

    lines = []
    for sym in sorted(symbols):
        lines.append('#undef %s' % sym)
        lines.append(
            'extern __typeof (%s) %s __attribute ((alias ("IA__%s"), '
            'visibility ("default")));'
            % (sym, sym, sym))
        lines.append('#define %s IA__%s' % (sym, sym))
    return '\n'.join(lines) + ('\n' if lines else '')